  'plan-done': { coins: 25 },
  'min-45': { carbs: 30 },
  'two-disc': { coins: 35 },
  streak: { carbs: 20 },
  'km-10': { carbs: 25 },
  brick: { coins: 35 },
  'pack-bag': { carbs: 10 },
